// Package tidelab converts units and bins readings for the tide laboratory.
package tidelab

import "fmt"

// FeetPerMetre is the number of feet in one metre.
const FeetPerMetre = 3.28084

// Reading is a measured length together with its unit (m, cm or ft).
type Reading struct {
	Value float64
	Unit  string
}

// Metres converts the reading to metres. It returns an error for an unknown unit.
func (r Reading) Metres() (float64, error) {
	return ToMetres(r.Value, r.Unit)
}

// ToMetres converts value from unit (m, cm or ft) to metres and returns an error for any other unit.
func ToMetres(value float64, unit string) (float64, error) {
	switch unit {
	case "m":
		return value, nil
	case "cm":
		return value / 100, nil
	case "ft":
		return value / FeetPerMetre, nil
	}
	return 0, fmt.Errorf("tidelab: unknown unit %q", unit)
}

// Clamp limits v to the closed range [lo, hi].
func Clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

// Bucketize counts values per bucket: the result has len(edges)+1 entries and a value equal to an edge falls into the upper bucket.
func Bucketize(values, edges []int) []int {
	counts := make([]int, len(edges)+1)
	for _, v := range values {
		i := 0
		for i < len(edges) && v >= edges[i] {
			i++
		}
		counts[i]++
	}
	return counts
}

