		}
		check := func(kind, name, text string) {
			if strings.TrimSpace(text) == "" {
				t.Errorf("%s %s has no doc comment", kind, name)
			} else if !strings.HasPrefix(text, name+" ") {
				t.Errorf("the doc comment of %s %s must start with its name", kind, name)
