// Package seedbank keeps the stock of a community seed bank.
package seedbank

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// MaxPackets is the most packets of one SKU the bank will hold.
const MaxPackets = 500

// ErrBadSKU is returned when a SKU is not of the form PREFIX-NUMBER with a known prefix.
var ErrBadSKU = errors.New("seedbank: bad sku")

// Lot is a number of packets of one SKU.
type Lot struct {
	SKU string
	Qty int
}

// Label returns the text printed on the packet label, for example "VEG #0042 x3".
func (l Lot) Label() string {
	prefix, num, err := ParseSKU(l.SKU)
	if err != nil {
		return "?"
	}
	return fmt.Sprintf("%s #%04d x%d", prefix, num, l.Qty)
}

// ParseSKU splits a SKU such as VEG-0042 into its prefix and number. It returns ErrBadSKU for unknown prefixes or non-numeric numbers.
func ParseSKU(code string) (string, int, error) {
	prefix, rest, ok := strings.Cut(code, "-")
	if !ok || (prefix != "VEG" && prefix != "HRB" && prefix != "FLW") {
		return "", 0, ErrBadSKU
	}
	n, err := strconv.Atoi(rest)
	if err != nil || n < 0 {
		return "", 0, ErrBadSKU
	}
	return prefix, n, nil
}

// Add puts qty packets of sku into stock and returns the new count. It fails if the SKU is malformed, qty is not positive, or MaxPackets would be exceeded.
func Add(stock map[string]int, sku string, qty int) (int, error) {
	if _, _, err := ParseSKU(sku); err != nil {
		return 0, err
	}
	if qty <= 0 || stock[sku]+qty > MaxPackets {
		return 0, fmt.Errorf("seedbank: cannot add %d packets of %s", qty, sku)
	}
	stock[sku] += qty
	return stock[sku], nil
}

// LowStock returns, in alphabetical order, the SKUs whose count is below threshold.
func LowStock(stock map[string]int, threshold int) []string {
	var out []string
	for sku, qty := range stock {
		if qty < threshold {
			out = append(out, sku)
		}
	}
	sort.Strings(out)
	return out
}

