// Package ferry has timetable helpers for the island ferry.
package ferry

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// DayMinutes is the number of minutes in a day.
const DayMinutes = 24 * 60

// ErrBadTime is returned for times that are not HH:MM in the 24-hour clock.
var ErrBadTime = errors.New("ferry: bad time")

// Window is a span of time in minutes after midnight; End is exclusive.
type Window struct {
	Start, End int
}

// Overlap returns how many minutes the two windows share, or 0 if they do not touch.
func (w Window) Overlap(o Window) int {
	start, end := w.Start, w.End
	if o.Start > start {
		start = o.Start
	}
	if o.End < end {
		end = o.End
	}
	if end < start {
		return 0
	}
	return end - start
}

// ParseTime converts HH:MM to minutes after midnight. It returns ErrBadTime for malformed or out-of-range input.
func ParseTime(s string) (int, error) {
	h, m, ok := strings.Cut(s, ":")
	if !ok {
		return 0, ErrBadTime
	}
	hours, err1 := strconv.Atoi(h)
	minutes, err2 := strconv.Atoi(m)
	if err1 != nil || err2 != nil || hours < 0 || hours > 23 || minutes < 0 || minutes > 59 {
		return 0, ErrBadTime
	}
	return hours*60 + minutes, nil
}

// FormatTime renders minutes after midnight as HH:MM, wrapping around at midnight (also for negative values).
func FormatTime(minutes int) string {
	minutes = ((minutes % DayMinutes) + DayMinutes) % DayMinutes
	return fmt.Sprintf("%02d:%02d", minutes/60, minutes%60)
}

// NextDeparture returns the first departure at or after now, or tomorrow's first departure (plus DayMinutes) when none is left today. The bool is false if there are no departures at all.
func NextDeparture(times []int, now int) (int, bool) {
	if len(times) == 0 {
		return 0, false
	}
	sorted := append([]int(nil), times...)
	sort.Ints(sorted)
	for _, t := range sorted {
		if t >= now {
			return t, true
		}
	}
	return sorted[0] + DayMinutes, true
}

